    'c4e8a1d7-3b62-4f95-8e07-2a9d5c61bf34',
    'Bản tin Dân vận khéo — phường Yên Nghĩa',
    'ban-tin-dan-van-kheo',
    'a4',
    '/tin/bg-bia.webp',
    '{"margin":60,"skipFirstPage":true,"skipLastPage":true,"header":{"enabled":true,"text":"BẢN TIN DÂN VẬN KHÉO · PHƯỜNG YÊN NGHĨA","align":"left","fontSize":18,"color":"#a20f1a","rule":true,"ruleColor":"#c8a227","ruleWidth":2,"pageNumber":true,"pageNumberAlign":"right"},"footer":{"enabled":false,"text":"","align":"left","fontSize":18,"color":"#0b3f8f","rule":false,"ruleColor":"#c8a227","ruleWidth":2,"pageNumber":false}}'::jsonb
  )
  returning id
)
insert into public.book_pages (book_id, sort_order, background, background_image, elements)
select b.id, p.ord, p.bg, p.bgimg, p.els::jsonb
