  (1, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t12","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"TRONG SỐ NÀY","fontSize":44,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.2},{"id":"t13","type":"text","x":60,"y":157,"w":680,"rotation":0,"content":"Tin bài các hoạt động của Uỷ ban MTTQ Việt Nam phường Yên Nghĩa\ntrong phong trào “Dân vận khéo”","fontSize":20,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":false,"italic":true,"align":"center","lineHeight":1.5},{"id":"t14","type":"text","x":60,"y":249,"w":44,"rotation":0,"content":"03","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t15","type":"text","x":118,"y":249,"w":622,"rotation":0,"content":"Yên Nghĩa quyết liệt tháo gỡ “5 điểm nghẽn” từ cơ sở","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t16","type":"text","x":60,"y":301,"w":44,"rotation":0,"content":"07","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t17","type":"text","x":118,"y":301,"w":622,"rotation":0,"content":"Lấy tuyên truyền từ cơ sở gỡ “điểm nghẽn”","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t18","type":"text","x":60,"y":353,"w":44,"rotation":0,"content":"12","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t19","type":"text","x":118,"y":353,"w":622,"rotation":0,"content":"Giải phóng mặt bằng Quốc lộ 6: Tạo đồng thuận trong dân","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t20","type":"text","x":60,"y":405,"w":44,"rotation":0,"content":"18","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t21","type":"text","x":118,"y":405,"w":622,"rotation":0,"content":"Cử tri kiến nghị tháo gỡ vướng mắc đất đai, hạ tầng","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t22","type":"text","x":60,"y":457,"w":44,"rotation":0,"content":"22","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t23","type":"text","x":118,"y":457,"w":622,"rotation":0,"content":"Ra mắt mô hình “3 rõ, 4 tốt” tháo gỡ điểm nghẽn đô thị","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t24","type":"text","x":60,"y":509,"w":44,"rotation":0,"content":"27","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t25","type":"text","x":118,"y":509,"w":622,"rotation":0,"content":"Phát động thi đua cao điểm tháo gỡ 5 điểm nghẽn","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t26","type":"text","x":60,"y":561,"w":44,"rotation":0,"content":"31","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t27","type":"text","x":118,"y":561,"w":622,"rotation":0,"content":"Động viên lực lượng tuyên truyền giải phóng mặt bằng","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t28","type":"text","x":60,"y":613,"w":44,"rotation":0,"content":"36","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t29","type":"text","x":118,"y":613,"w":622,"rotation":0,"content":"Đẩy nhanh tiến độ giải phóng mặt bằng Quốc lộ 6","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t30","type":"text","x":60,"y":665,"w":44,"rotation":0,"content":"43","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#c8a227","bold":true,"italic":false,"align":"right","lineHeight":1.4},{"id":"t31","type":"text","x":118,"y":665,"w":622,"rotation":0,"content":"Đi từng ngõ, gõ từng nhà, gỡ từng vướng mắc","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.4},{"id":"t32","type":"text","x":60,"y":717,"w":680,"rotation":0,"content":"Nội dung và hình ảnh trong số này do Uỷ ban MTTQ Việt Nam phường Yên Nghĩa cung cấp, tổng hợp từ các tin bài về hoạt động của Mặt trận phường trong phong trào “Dân vận khéo”.","fontSize":20,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":true,"align":"left","lineHeight":1.55}]'),
  (2, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t33","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"CÔNG TÁC MẶT TRẬN","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t34","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Yên Nghĩa quyết liệt tháo gỡ “5 điểm nghẽn” từ cơ sở","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t35","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Nguồn: Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i36","type":"image","x":60,"y":262,"w":680,"h":348,"rotation":0,"src":"/tin/dvk/quyet-liet-1.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t37","type":"text","x":60,"y":618,"w":680,"rotation":0,"content":"Lễ ký kết chương trình phối hợp năm 2026 giữa Công an phường và Ủy ban MTTQ Việt Nam phường trong công tác tuyên truyền, vận động nhân dân tham gia tháo gỡ “5 điểm nghẽn” trên địa bàn. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t38","type":"text","x":60,"y":703,"w":680,"rotation":0,"content":"Sáng 23-4, phường Yên Nghĩa tổ chức hội nghị chào mừng các ngày lễ lớn, tuyên truyền nghị quyết của Đảng, triển khai nhiệm vụ quý II-2026 và ký kết chương trình phối hợp giữa Công an phường với Ủy ban MTTQ Việt Nam phường.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (3, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i39","type":"image","x":60,"y":96,"w":207,"h":107,"rotation":0,"src":"/tin/dvk/quyet-liet-2.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t40","type":"text","x":60,"y":211,"w":328,"rotation":0,"content":"Phó Trưởng Công an phường Yên Nghĩa Trung tá Phan Hồ Quân phát biểu tham luận tại hội nghị. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t41","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Tại hội nghị, các đại biểu ôn lại ý nghĩa lịch sử của các ngày lễ lớn, qua đó giáo dục truyền thống, khơi dậy tinh thần trách nhiệm trong xây dựng địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t42","type":"text","x":60,"y":302,"w":680,"rotation":0,"content":"Đồng thời, hội nghị phổ biến những nội dung cốt lõi của Nghị quyết số 02-NQ/TW và kết quả Hội nghị Trung ương 2 khóa XIV, giúp cán bộ, đảng viên và nhân dân nắm vững định hướng lớn trong giai đoạn mới.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t43","type":"text","x":60,"y":430,"w":680,"rotation":0,"content":"Điểm nhấn của hội nghị là lễ ký kết chương trình phối hợp năm 2026 giữa Công an phường và Ủy ban MTTQ Việt Nam phường, nhằm đẩy mạnh tuyên truyền, vận động nhân dân tham gia tháo gỡ “5 điểm nghẽn” trên địa bàn, nhất là trong các lĩnh vực trật tự đô thị, vệ sinh môi trường, đất đai, xây dựng.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (4, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i44","type":"image","x":412,"y":96,"w":328,"h":177,"rotation":0,"src":"/tin/dvk/quyet-liet-3.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t45","type":"text","x":412,"y":281,"w":328,"rotation":0,"content":"Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa Lương Huệ Minh phát biểu. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t46","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Phó Chủ tịch Ủy ban MTTQ Việt Nam phường Lương Thị Hồng cho biết, thời gian qua, MTTQ và các đoàn thể đã phối hợp triển khai nhiều giải pháp đồng bộ, góp phần giữ vững ổn định cơ sở;","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t47","type":"text","x":60,"y":372,"w":680,"rotation":0,"content":"công tác tuyên truyền, vận động từng bước đi vào nền nếp và đạt kết quả tích cực.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t48","type":"text","x":60,"y":463,"w":680,"rotation":0,"content":"Hội nghị ghi nhận nhiều tham luận tâm huyết của đại diện các đoàn thể, Công an phường, đội ngũ giáo viên và các tổ dân phố. Các ý kiến tập trung phân tích rõ thực trạng, nguyên nhân của các “điểm nghẽn”, đồng thời đề xuất nhiều giải pháp cụ thể, thiết thực. Nhiều ý kiến nhấn mạnh cần phát huy vai trò tự quản của cộng đồng dân cư, kịp thời phát hiện, xử lý các vấn đề ngay từ cơ sở, không để phát sinh phức tạp.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t49","type":"text","x":60,"y":701,"w":680,"rotation":0,"content":"Kết luận hội nghị, Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa Lương Huệ Minh đề nghị các ban, ngành, đoàn thể tiếp tục đổi mới phương thức tuyên truyền, ứng dụng công nghệ thông tin, phát huy vai trò chủ thể của Nhân dân, kịp thời nắm bắt và giải quyết các vấn đề phát sinh từ cơ sở.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (5, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t50","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Tại hội nghị, phường Yên Nghĩa phát động ủng hộ Quỹ “Vì biển, đảo Việt Nam” năm 2026, kêu gọi cán bộ, đảng viên và nhân dân phát huy tinh thần đoàn kết, chung tay hướng về biển đảo quê hương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i51","type":"image","x":60,"y":222,"w":681,"h":383,"rotation":0,"src":"/tin/dvk/quyet-liet-4.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t52","type":"text","x":60,"y":613,"w":680,"rotation":0,"content":"Ngay sau lễ phát động, đông đảo cán bộ phường Yên Nghĩa ủng hộ Quỹ “Vì biển, đảo Việt Nam” năm 2026. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t53","type":"text","x":60,"y":675,"w":680,"rotation":0,"content":"Ngay sau hội nghị, phường đã tổ chức ra quân tuyên truyền về “5 điểm nghẽn” thu hút đông đảo cán bộ và nhân dân tham gia, tạo khí thế thi đua sôi nổi trên địa bàn; góp phần củng cố sự đồng thuận, phát huy sức mạnh đại đoàn kết toàn dân, hướng tới xây dựng phường Yên Nghĩa ngày càng văn minh, phát triển bền vững.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (6, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t54","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"DÂN VẬN KHÉO","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t55","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Phường Yên Nghĩa: Lấy tuyên truyền từ cơ sở gỡ “điểm nghẽn”","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t56","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Nguồn: Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i57","type":"image","x":108,"y":262,"w":585,"h":390,"rotation":0,"src":"/tin/dvk/tuyen-truyen-co-so-1.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t58","type":"text","x":60,"y":660,"w":680,"rotation":0,"content":"Mô hình “Tuyến đường quân - dân tự quản” đã trở thành điểm sáng tại tổ dân phố 17 phường Yên Nghĩa. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t59","type":"text","x":60,"y":722,"w":680,"rotation":0,"content":"Lấy tuyên truyền từ cơ sở làm khâu đột phá, phường Yên Nghĩa từng bước tháo gỡ các “điểm nghẽn” trong quản lý đô thị. Từ điểm sáng tại tổ dân phố 17, cách làm bám sát từng hộ dân, từng khu dân cư đã tạo đồng thuận trong nhân dân, cho thấy khi tuyên truyền đúng và trúng, những việc khó cũng có thể giải quyết hiệu quả, bền vững.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (7, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t60","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Tuyên truyền đúng, đồng thuận cao, hiệu quả rõ","fontSize":26,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t61","type":"text","x":60,"y":141,"w":680,"rotation":0,"content":"Thực tiễn quản lý đô thị cho thấy, nhiều vấn đề tồn tại kéo dài không hẳn do thiếu quy định, mà do chưa tạo được sự đồng thuận trong nhân dân. Từ nhận thức đó, Yên Nghĩa không đặt trọng tâm vào xử lý vi phạm, mà ưu tiên làm tốt công tác tuyên truyền, vận động, coi đây là “chìa khóa” để giải quyết tận gốc vấn đề.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i62","type":"image","x":60,"y":341,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/tuyen-truyen-co-so-2.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t63","type":"text","x":60,"y":534,"w":328,"rotation":0,"content":"Các hộ dân trên địa bàn tổ dân phố 17 phường Yên Nghĩa tháo dỡ, bàn giao mặt bằng. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t64","type":"text","x":412,"y":341,"w":328,"rotation":0,"content":"Theo Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa Lương Huệ Minh, công tác tuyên truyền chỉ thực sự hiệu quả khi bám sát cơ sở, gắn với những vấn đề cụ thể của người dân: “Chúng tôi xác định phải đưa chủ trương đến đúng","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t65","type":"text","x":60,"y":625,"w":680,"rotation":0,"content":"đối tượng, đúng thời điểm, bằng những hình thức phù hợp, dễ hiểu, dễ tiếp cận. Khi người dân hiểu rõ quyền lợi và trách nhiệm của mình, họ sẽ chủ động tham gia, từ đó tạo sự đồng thuận trong triển khai các nhiệm vụ tại địa phương”.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t66","type":"text","x":60,"y":790,"w":680,"rotation":0,"content":"Với phương châm “Dân biết, dân bàn, dân làm, dân kiểm tra, dân thụ hưởng”, công tác tuyên truyền được triển khai linh hoạt, đa dạng, bám sát từng địa bàn.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (8, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t67","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Nội dung tuyên truyền không chỉ dừng ở việc phổ biến chủ trương, chính sách, mà còn gắn với những vấn đề cụ thể, thiết thực trong đời sống hằng ngày của người dân.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i68","type":"image","x":412,"y":222,"w":328,"h":219,"rotation":0,"src":"/tin/dvk/tuyen-truyen-co-so-3.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t69","type":"text","x":412,"y":449,"w":328,"rotation":0,"content":"Dự án Vành đai 4 trên địa bàn phường Yên Nghĩa. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t70","type":"text","x":60,"y":222,"w":328,"rotation":0,"content":"Tại tổ dân phố 17, mô hình “Tuyến đường quân - dân tự quản” đã trở thành điểm sáng.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t71","type":"text","x":60,"y":517,"w":680,"rotation":0,"content":"Không chỉ dừng ở khẩu hiệu, mô hình được duy trì bằng những việc làm cụ thể: Người dân tự giác giữ gìn vệ sinh môi trường, chỉnh trang cảnh quan, tham gia giám sát trật tự đô thị.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t72","type":"text","x":60,"y":645,"w":680,"rotation":0,"content":"Ông Bùi Văn Binh, Bí thư Chi bộ, Trưởng ban Công tác Mặt trận tổ dân phố 17 cho biết: “Muốn người dân làm theo, trước hết, cán bộ, đảng viên phải gương mẫu, sau đó là kiên trì tuyên truyền để người dân hiểu. Khi đã hiểu đúng, người dân sẽ tự giác thực hiện, không cần nhắc nhở nhiều”.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t73","type":"text","x":60,"y":808,"w":680,"rotation":0,"content":"Việc triển khai không theo phong trào, mà duy trì thường xuyên, liên tục. Từ năm 2024, chi bộ đã tổ chức họp dân, lồng ghép nội dung vào Ngày hội Đại đoàn kết, triển khai, phổ biến nghị quyết đến từng hộ gia đình.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (9, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t74","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Với 25 hộ dân và 4 cơ quan trên địa bàn, công tác vận động giải phóng mặt bằng các dự án như Vành đai 4 và dự án quốc lộ 6 đạt kết quả tích cực: 15/17 hộ đã chấp hành tháo dỡ, 2 hộ còn lại đồng thuận và cam kết hoàn trả mặt bằng trước ngày 30-6”, ông Binh nhấn mạnh.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t75","type":"text","x":60,"y":259,"w":680,"rotation":0,"content":"Từ cách làm ở cơ sở đến hướng đi bền vững","fontSize":26,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t76","type":"text","x":60,"y":304,"w":680,"rotation":0,"content":"Từ một tổ dân phố, có thể thấy rõ cách tiếp cận của Yên Nghĩa trong tháo gỡ “5 điểm nghẽn”: Không làm theo phong trào, không nóng vội, mà kiên trì xây dựng nền tảng nhận thức trong nhân dân. Đây cũng là yếu tố quyết định để xử lý các vấn đề như trật tự đô thị, an toàn giao thông, vệ sinh môi trường, hay xây dựng nếp sống văn minh.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t77","type":"text","x":60,"y":504,"w":680,"rotation":0,"content":"Trong bối cảnh đô thị hóa nhanh, áp lực quản lý ngày càng lớn, nếu chỉ dựa vào lực lượng chức năng thì khó tạo chuyển biến bền vững. Ngược lại, khi người dân trở thành chủ thể, chủ động tham gia và tự giác chấp hành, hiệu quả đạt được sẽ sâu và lâu dài hơn.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t78","type":"text","x":60,"y":667,"w":680,"rotation":0,"content":"Ủy ban Mặt trận Tổ quốc phường và các đoàn thể tiếp tục giữ vai trò nòng cốt trong công tác tuyên truyền, đồng thời, tăng cường nắm bắt dư luận xã hội, kịp thời phản ánh và giải quyết những vấn đề phát sinh ngay từ cơ sở. Đây không chỉ là giải pháp trước mắt, mà còn là hướng đi chiến lược, góp phần củng cố niềm tin của nhân dân, tạo sự thống nhất trong toàn hệ thống chính trị.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (10, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t79","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Có thể khẳng định, lấy tuyên truyền cơ sở làm khâu đột phá không chỉ giúp Yên Nghĩa tháo gỡ những “điểm nghẽn” trước mắt, mà còn tạo nền tảng quan trọng để xây dựng đô thị văn minh, kỷ cương. Khi mỗi chủ trương được “thấm” đến từng người dân, được chuyển hóa thành hành động tự giác, đó chính là lúc sức mạnh nội sinh được khơi dậy - yếu tố quyết định cho sự phát triển bền vững.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (11, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t80","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"GIẢI PHÓNG MẶT BẰNG","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t81","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Giải phóng mặt bằng Quốc lộ 6 đoạn qua Yên Nghĩa: Đẩy mạnh tuyên truyền, tạo đồng thuận trong dân","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t82","type":"text","x":60,"y":264,"w":680,"rotation":0,"content":"Nguồn: Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i83","type":"image","x":108,"y":303,"w":585,"h":390,"rotation":0,"src":"/tin/dvk/gpmb-dong-thuan-1.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t84","type":"text","x":60,"y":701,"w":680,"rotation":0,"content":"Công tác giải phóng mặt bằng Dự án cải tạo, nâng cấp quốc lộ 6 qua Yên Nghĩa đang được triển khai đồng bộ nhằm đảm bảo tiến độ theo yêu cầu của thành phố. Ảnh: NT.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t85","type":"text","x":60,"y":763,"w":680,"rotation":0,"content":"Công tác giải phóng mặt bằng (GPMB) Dự án cải tạo, nâng cấp quốc lộ 6 (đoạn Ba La - Xuân Mai) đang được phường Yên Nghĩa tập trung triển khai nhằm đảm bảo tiến độ theo yêu cầu của thành phố. Tuy nhiên, bên cạnh những khó khăn về giá đất bồi thường, việc thiếu quỹ đất tái định cư đang trở thành “điểm nghẽn” lớn cần sớm được tháo gỡ để tạo sự đồng thuận trong nhân dân.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (12, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t86","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Áp lực lớn từ nhu cầu tái định cư","fontSize":26,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t87","type":"text","x":60,"y":141,"w":680,"rotation":0,"content":"Dự án cải tạo, nâng cấp quốc lộ 6 là công trình giao thông trọng điểm của Thủ đô, với quy mô thu hồi đất lớn, dự án tác động trực tiếp tới hàng trăm hộ dân trên địa bàn phường Yên Nghĩa.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i88","type":"image","x":60,"y":267,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/gpmb-dong-thuan-2.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t89","type":"text","x":60,"y":460,"w":328,"rotation":0,"content":"Chủ tịch UBND phường Yên Nghĩa Lê Xuân Hoàn (áo trắng ở giữa) tuyên truyền, đối thoại với người dân nhằm tạo đồng thuận trong công tác giải phóng mặt bằng Dự án nâng cấp quốc lộ 6. Ảnh NT.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t90","type":"text","x":412,"y":267,"w":328,"rotation":0,"content":"Theo UBND phường Yên Nghĩa, dự án có tổng diện tích thu hồi khoảng 124.297,5m², liên quan đến 528 hộ gia đình, cá nhân có đất ở; 46 hộ có đất thương mại dịch vụ; 16 hộ có đất nông nghiệp cùng nhiều tổ chức, doanh nghiệp trên địa bàn.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t91","type":"text","x":60,"y":599,"w":680,"rotation":0,"content":"Ngoài ra, còn hơn 79.268m² đất giao thông, thủy lợi và đất công do địa phương quản lý nằm trong phạm vi thực hiện dự án.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t92","type":"text","x":60,"y":690,"w":680,"rotation":0,"content":"Đến nay, địa phương đã ban hành 601 thông báo thu hồi đất với diện tích hơn 11,2ha; xác nhận nguồn gốc đất cho 44 trường hợp để phục vụ lập phương án bồi thường; niêm yết dự thảo phương án bồi thường, hỗ trợ đối với 43 trường hợp. Đồng thời, hơn 68.452m² đất công đã được bàn giao cho chủ đầu tư để phục vụ thi công dự án.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (13, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i93","type":"image","x":412,"y":96,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/gpmb-dong-thuan-3.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t94","type":"text","x":412,"y":289,"w":328,"rotation":0,"content":"Bí thư Đảng ủy, Chủ tịch HĐND phường Yên Nghĩa Nguyễn Nguyên Quân tại hội nghị Ban Chỉ đạo GPMB Dự án cải tạo, nâng cấp quốc lộ 6, nhằm tháo gỡ các khó khăn, vướng mắc trong quá trình triển khai. Ảnh NT.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t95","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Tuy nhiên, qua rà soát, dự kiến có khoảng 320 hộ cần bố trí tái định cư với tổng diện tích khoảng 2,1ha, trong khi quỹ đất tái định cư hiện có mới khoảng 1,5ha. Việc thiếu quỹ tái định cư khiến nhiều hộ dân còn băn khoăn, lo lắng về nơi ở sau khi bị thu hồi đất.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t96","type":"text","x":60,"y":452,"w":680,"rotation":0,"content":"Trước đó, tại cuộc họp Ban Chỉ đạo GPMB dự án (ngày 8-5), nhiều ý kiến đề nghị thành phố sớm bổ sung quỹ đất, quỹ nhà tái định cư nhằm đảm bảo quyền lợi cho người dân. Một số trường hợp nhiều hộ cùng sinh sống trên một thửa đất cũng được kiến nghị cần có hướng dẫn cụ thể để giải quyết phù hợp thực tế.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t97","type":"text","x":60,"y":652,"w":680,"rotation":0,"content":"Bên cạnh vấn đề tái định cư, việc xử lý các trường hợp đất dịch vụ, đất giao không đúng thẩm quyền từ nhiều năm trước cũng đang đặt ra nhiều khó khăn cho địa phương trong quá trình triển khai GPMB.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (14, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i98","type":"image","x":60,"y":96,"w":680,"h":455,"rotation":0,"src":"/tin/dvk/gpmb-dong-thuan-4.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t99","type":"text","x":60,"y":559,"w":680,"rotation":0,"content":"Khu vực giao cắt giữa Dự án Vành đai 4 - Vùng Thủ đô Hà Nội và Quốc lộ 6 đoạn qua phường Yên Nghĩa đang được đẩy nhanh tiến độ triển khai. Ảnh NT.","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t100","type":"text","x":60,"y":621,"w":680,"rotation":0,"content":"Tạo đồng thuận để đẩy nhanh tiến độ","fontSize":26,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t101","type":"text","x":60,"y":666,"w":680,"rotation":0,"content":"Theo UBND phường Yên Nghĩa, một trong những “điểm nghẽn” hiện nay là sự chênh lệch giá đất bồi thường giữa Dự án quốc lộ 6 và Dự án Vành đai 4 - Vùng Thủ đô Hà Nội trên cùng trục quốc lộ 6A.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t102","type":"text","x":60,"y":792,"w":680,"rotation":0,"content":"Cụ thể, tại vị trí 1 trên quốc lộ 6A đoạn từ đường sắt đến cầu Mai Lĩnh, giá bồi thường của Dự án Vành đai 4 được phê duyệt hơn 90,8 triệu đồng/m², trong khi mức áp dụng đối với dự án quốc lộ 6 hiện khoảng","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (15, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t103","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"52,3 triệu đồng/m². Sự chênh lệch này khiến nhiều hộ dân so sánh và chưa thực sự đồng thuận.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t104","type":"text","x":60,"y":185,"w":680,"rotation":0,"content":"Ngoài ra, dự án còn liên quan đến 24 thửa đất dịch vụ bị thu hồi với diện tích khoảng 500m². Nhiều hộ dân mong muốn được bố trí đất có cùng mục đích sử dụng thay vì chỉ nhận bồi thường bằng tiền để ổn định sinh kế lâu dài.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t105","type":"text","x":60,"y":348,"w":680,"rotation":0,"content":"Hiện địa phương đang tập trung rà soát hồ sơ, kiểm đếm, xác minh nguồn gốc đất và hoàn thiện các thủ tục liên quan đến tái định cư. Trong đó, đã hoàn thành biên bản kiểm đếm đối với 108 trường hợp để phục vụ xây dựng phương án bồi thường, hỗ trợ và tái định cư.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t106","type":"text","x":60,"y":511,"w":680,"rotation":0,"content":"Một khó khăn khác là tiến độ hoàn thiện bản đồ thu hồi đất còn chậm. Toàn tuyến có 18 tờ bản đồ nhưng hiện mới hoàn thiện ký xác nhận được 4 tờ. Các đơn vị liên quan đang tiếp tục đẩy nhanh tiến độ hoàn thiện hồ sơ để phục vụ các bước tiếp theo của công tác GPMB.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t107","type":"text","x":60,"y":674,"w":680,"rotation":0,"content":"Chủ tịch UBND phường Yên Nghĩa Lê Xuân Hoàn cho biết, địa phương đang tăng cường đối thoại trực tiếp với người dân nhằm tháo gỡ từng khó khăn cụ thể ngay từ cơ sở.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t108","type":"text","x":60,"y":800,"w":680,"rotation":0,"content":"“Quan điểm của phường là thực hiện đúng quy định của pháp luật nhưng phải đảm bảo hài hòa lợi ích giữa Nhà nước và người dân.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (16, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t109","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Những nội dung vượt thẩm quyền sẽ được tổng hợp, báo cáo thành phố và các sở, ngành xem xét giải quyết để tạo sự đồng thuận cao nhất trong quá trình triển khai dự án”, ông Lê Xuân Hoàn nhấn mạnh.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t110","type":"text","x":60,"y":222,"w":680,"rotation":0,"content":"Bí thư Đảng ủy, Chủ tịch HĐND phường Yên Nghĩa Nguyễn Nguyên Quân khẳng định, công tác giải phóng mặt bằng Dự án cải tạo, nâng cấp quốc lộ 6 là nhiệm vụ trọng tâm, xuyên suốt của phường trong năm 2026 và thời gian tới. Bí thư Đảng ủy phường yêu cầu cả hệ thống chính trị phải vào cuộc đồng bộ, quyết liệt, xác định rõ trách nhiệm trong công tác tuyên truyền, vận động và tạo sự đồng thuận trong nhân dân.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t111","type":"text","x":60,"y":460,"w":680,"rotation":0,"content":"Theo ông Nguyễn Nguyên Quân, các đoàn thể chính trị - xã hội cần tập trung bám sát địa bàn, chủ động nắm bắt tâm tư, nguyện vọng của người dân; tăng cường đối thoại, tuyên truyền để người dân hiểu rõ ý nghĩa, tầm quan trọng của dự án đối với sự phát triển hạ tầng khu vực phía Tây Thủ đô. Đồng thời, các bộ phận chuyên môn phải chủ động rà soát, kịp thời tháo gỡ khó khăn ngay từ cơ sở, không để phát sinh các điểm nóng, góp phần đảm bảo tiến độ GPMB theo yêu cầu của thành phố.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t112","type":"text","x":60,"y":735,"w":680,"rotation":0,"content":"Cùng với Dự án Vành đai 4 - Vùng Thủ đô Hà Nội, việc cải tạo, nâng cấp quốc lộ 6 sẽ mở ra không gian phát triển mới cho khu vực phía Tây Hà Nội. Vì vậy, tháo gỡ kịp thời những khó khăn về tái định cư, giá đất và cơ chế hỗ trợ được xem là yếu tố quan trọng để đẩy nhanh tiến độ GPMB, tạo đồng thuận trong nhân dân và sớm đưa dự án về đích theo kế hoạch.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (17, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t113","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"TIẾP XÚC CỬ TRI","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t114","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Cử tri Yên Nghĩa kiến nghị tháo gỡ vướng mắc về đất đai, hạ tầng dân sinh","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t115","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Nguồn: Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i116","type":"image","x":107,"y":262,"w":586,"h":440,"rotation":0,"src":"/tin/dvk/cu-tri-1.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t117","type":"text","x":60,"y":710,"w":680,"rotation":0,"content":"Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa Lương Huệ Minh báo cáo cử tri.Ảnh: Vân Nga","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t118","type":"text","x":60,"y":772,"w":680,"rotation":0,"content":"Sáng 5-6, Tổ đại biểu HĐND phường Yên Nghĩa khóa II, nhiệm kỳ 2026-2031 đã tiếp xúc cử tri tại tổ dân phố số 32 trước kỳ họp thứ hai HĐND phường. Nhiều ý kiến, kiến nghị của cử tri tập trung vào các vấn đề đất đai, hạ tầng và đời sống dân sinh.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (18, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i119","type":"image","x":60,"y":96,"w":328,"h":230,"rotation":0,"src":"/tin/dvk/cu-tri-2.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t120","type":"text","x":60,"y":334,"w":328,"rotation":0,"content":"Trưởng phòng Kinh tế Hạ tầng đầu tư Phạm Anh Tuấn làm rõ một số nội dung cử tri nêu.Ảnh: Vân Nga","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t121","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Tại hội nghị, Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa Lương Huệ Minh đã báo cáo với cử tri về tình hình phát triển kinh tế - xã hội 6 tháng đầu năm 2026 và dự kiến nội dung, chương trình kỳ họp thứ Hai HĐND phường khóa II, nhiệm kỳ","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t122","type":"text","x":60,"y":425,"w":680,"rotation":0,"content":"2026-2031.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t123","type":"text","x":60,"y":478,"w":680,"rotation":0,"content":"Theo đó, kinh tế địa phương tiếp tục duy trì đà tăng trưởng, các nhiệm vụ phát triển kinh tế - xã hội được triển khai đồng bộ. Công tác an sinh xã hội được bảo đảm, đời sống nhân dân tiếp tục được cải thiện. Các lĩnh vực văn hóa, giáo dục, y tế, vệ sinh môi trường được quan tâm; tỷ lệ người dân tham gia bảo hiểm y tế duy trì ở mức cao; công tác giải quyết việc làm và chăm lo các đối tượng chính sách được thực hiện đầy đủ, kịp thời.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (19, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i124","type":"image","x":412,"y":96,"w":328,"h":244,"rotation":0,"src":"/tin/dvk/cu-tri-3.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t125","type":"text","x":412,"y":348,"w":328,"rotation":0,"content":"Bí thư Đảng ủy, Chủ tịch HĐND phường Yên Nghĩa Nguyễn Nguyên Quân kết luận. Ảnh: Vân Nga","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t126","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Trong không khí dân chủ, thẳng thắn, các cử tri đã phản ánh nhiều vấn đề còn tồn tại trên địa bàn, kiến nghị liên quan đến công tác quản lý đất đai, đề nghị các cơ quan chức năng đẩy nhanh tiến độ cấp giấy chứng nhận quyền sử dụng đất và sớm giải quyết các","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t127","type":"text","x":60,"y":439,"w":680,"rotation":0,"content":"quyền lợi liên quan đến đất dịch vụ đối với những hộ dân có đất bị thu hồi...","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t128","type":"text","x":60,"y":530,"w":680,"rotation":0,"content":"Bên cạnh đó, cử tri đề nghị phường quan tâm đầu tư, nâng cấp hệ thống giao thông, cải thiện hệ thống thoát nước nhằm khắc phục tình trạng ngập úng cục bộ; đồng thời sớm cải tạo nâng cấp nhà văn hóa để đáp ứng nhu cầu sinh hoạt cộng đồng của nhân dân.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t129","type":"text","x":60,"y":693,"w":680,"rotation":0,"content":"Nhiều ý kiến cũng đề xuất tăng cường hỗ trợ đào tạo nghề, chuyển đổi việc làm, nâng cao thu nhập và chất lượng cuộc sống của người dân. Cử tri mong muốn các cấp chính quyền có giải pháp thiết thực, xử lý dứt điểm những tồn tại kéo dài, góp phần ổn định đời sống và củng cố niềm tin của nhân dân.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (20, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t130","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Sau khi nghe các ý kiến, kiến nghị của cử tri, đại diện các cơ quan chuyên môn của phường đã trao đổi, làm rõ một số nội dung thuộc thẩm quyền.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t131","type":"text","x":60,"y":222,"w":680,"rotation":0,"content":"Thay mặt Tổ đại biểu, Bí thư Đảng ủy, Chủ tịch HĐND phường Yên Nghĩa Nguyễn Nguyên Quân tiếp thu toàn bộ các ý kiến, kiến nghị của cử tri; giải đáp một số vấn đề thuộc thẩm quyền của phường; đồng thời khẳng định các ý kiến sẽ được tổng hợp, báo cáo tại kỳ họp thứ Hai HĐND phường và chuyển các cơ quan có thẩm quyền xem xét, giải quyết theo quy định.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (21, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t132","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"MÔ HÌNH MỚI","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t133","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"MTTQ Yên Nghĩa ra mắt mô hình “3 rõ, 4 tốt” tháo gỡ điểm nghẽn đô thị","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t134","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Nguồn: Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i135","type":"image","x":60,"y":262,"w":680,"h":346,"rotation":0,"src":"/tin/dvk/ba-ro-bon-tot-1.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t136","type":"text","x":60,"y":616,"w":680,"rotation":0,"content":"Văn nghệ chào mừng tại hội nghị. Ảnh: NT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t137","type":"text","x":60,"y":654,"w":680,"rotation":0,"content":"Ngày 13-5, Ủy ban MTTQ Việt Nam phường Yên Nghĩa tổ chức hội nghị triển khai nhiệm vụ chào mừng Đại hội MTTQ Việt Nam nhiệm kỳ 2026-2031 và kỷ niệm 136 năm Ngày sinh Chủ tịch Hồ Chí Minh; Hội nghị ra mắt mô hình “Tổ tuyên truyền 3 rõ, 4 tốt”, nhóm “Alo Đoàn kết vì Yên Nghĩa hôm nay” và phát động cao điểm tuyên truyền, vận động giải phóng mặt bằng Dự án Quốc lộ 6 đoạn Ba La - Xuân Mai.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (22, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i138","type":"image","x":60,"y":96,"w":328,"h":196,"rotation":0,"src":"/tin/dvk/ba-ro-bon-tot-2.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t139","type":"text","x":60,"y":300,"w":328,"rotation":0,"content":"Đại biểu tham gia hội nghị. Ảnh: NT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t140","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Tại hội nghị, Ban Thường trực Ủy ban MTTQ Việt Nam phường Yên Nghĩa đã triển khai kế hoạch tuyên truyền sâu rộng trong cán bộ, đoàn viên, hội viên và các tầng lớp nhân dân về ý nghĩa lịch sử của Ngày","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t141","type":"text","x":60,"y":344,"w":680,"rotation":0,"content":"Toàn quốc kháng chiến; công lao to lớn của Chủ tịch Hồ Chí Minh đối với sự nghiệp cách mạng của dân tộc; đồng thời tạo khí thế thi đua sôi nổi chào mừng Đại hội MTTQ Việt Nam các cấp nhiệm kỳ 2026-2031.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t142","type":"text","x":60,"y":472,"w":680,"rotation":0,"content":"Một trong những nội dung đáng chú ý tại hội nghị là việc triển khai kế hoạch tuyên truyền, vận động thực hiện dự án cải tạo, nâng cấp Quốc lộ 6 đoạn Ba La - Xuân Mai qua địa bàn phường Yên Nghĩa. Đây là dự án giao thông trọng điểm có ý nghĩa quan trọng đối với phát triển hạ tầng khu vực phía Tây Thủ đô.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (23, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i143","type":"image","x":412,"y":96,"w":328,"h":177,"rotation":0,"src":"/tin/dvk/ba-ro-bon-tot-3.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t144","type":"text","x":412,"y":281,"w":328,"rotation":0,"content":"Phó Chủ tịch MTTQ Việt Nam phường Yên Nghĩa Đoàn Viết Mạnh thông báo triển khai mô hình “Tổ tuyên truyền 03 rõ, 4 tốt” gắn với tiếp nhận ý kiến nhân dân và tham gia tháo gỡ 5 điểm nghẽn trên địa bàn phường. Ảnh: NT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t145","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Ủy ban MTTQ Việt Nam phường đã thành lập tổ công tác gồm 4 nhóm phụ trách từng địa bàn dân cư để trực tiếp tuyên truyền, vận động các hộ dân trong diện thu hồi đất.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t146","type":"text","x":60,"y":444,"w":680,"rotation":0,"content":"Theo lộ trình đề ra, từ nay đến hết tháng 5-2026, phường tập trung tuyên truyền, vận động gần 300 hộ dân phối hợp thực hiện đo đạc, kiểm đếm. Đầu tháng 6-2026 sẽ tiếp tục vận động các hộ đồng thuận với phương án bồi thường, hỗ trợ, tái định cư; phấn đấu hoàn thành bàn giao toàn bộ mặt bằng trước ngày 30-6-2026.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t147","type":"text","x":60,"y":646,"w":680,"rotation":0,"content":"Bên cạnh đó, hội nghị cũng triển khai mô hình “Tổ tuyên truyền 3 rõ, 4 tốt” gắn với tiếp nhận ý kiến nhân dân và tham gia tháo gỡ 5 điểm nghẽn trên địa bàn phường gồm: Ùn tắc giao thông, ô nhiễm môi trường, ngập úng đô thị, vi phạm trật tự xây dựng - đất đai và an toàn thực phẩm.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t148","type":"text","x":60,"y":809,"w":680,"rotation":0,"content":"Mô hình hướng tới xây dựng lực lượng tuyên truyền “gần dân, sát dân”, chủ động nắm bắt tình hình ngay từ cơ sở, đồng thời phát huy vai trò giám sát cộng đồng, tăng cường phối hợp giữa MTTQ, chính quyền và","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (24, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t149","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"các đoàn thể trong xử lý các vấn đề dân sinh.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i150","type":"image","x":60,"y":147,"w":680,"h":372,"rotation":0,"src":"/tin/dvk/ba-ro-bon-tot-4.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t151","type":"text","x":60,"y":527,"w":680,"rotation":0,"content":"Chủ tịch Ủy ban MTTQ Việt Nam phường Lương Huệ Minh phát biểu tại hội nghị. Ảnh: NT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t152","type":"text","x":60,"y":565,"w":680,"rotation":0,"content":"Tại hội nghị, Ủy ban MTTQ Việt Nam phường Yên Nghĩa cũng công bố quyết định thành lập Ban Điều hành nhóm kết nối “Alo Đoàn kết vì Yên Nghĩa hôm nay”, do Chủ tịch Ủy ban MTTQ Việt Nam phường Lương Huệ Minh làm Trưởng ban điều hành. Nhóm sẽ trở thành kênh tiếp nhận, phản ánh nhanh các vấn đề dân sinh, trật tự đô thị, môi trường, an ninh trật tự… từ cơ sở để kịp thời chuyển tải đến các cơ quan chức năng xem xét giải quyết.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (25, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t153","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Phát biểu tại hội nghị, lãnh đạo phường Yên Nghĩa đề nghị các tổ chức đoàn thể, ban công tác Mặt trận và hệ thống chính trị cơ sở phát huy tinh thần trách nhiệm, tăng cường tuyên truyền, vận động nân dân tham gia hưởng ứng các phong trào thi đua yêu nước, xây dựng đô thị văn minh; đồng thời chủ động nắm bắt dư luận xã hội, kịp thời phản ánh những vấn đề phát sinh ngay từ cơ sở, góp phần giữ vững ổn định chính trị và tạo đồng thuận xã hội trên địa bàn.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (26, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t154","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"THI ĐUA","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t155","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Phường Yên Nghĩa phát động thi đua cao điểm tháo gỡ 5 điểm nghẽn từ cơ sở","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t156","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Nguồn: Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i157","type":"image","x":61,"y":262,"w":679,"h":312,"rotation":0,"src":"/tin/dvk/thi-dua-1.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t158","type":"text","x":60,"y":582,"w":680,"rotation":0,"content":"Quang cảnh hội nghị. Ảnh: PT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t159","type":"text","x":60,"y":620,"w":680,"rotation":0,"content":"Ngày 19-6, Ban Thường trực Ủy ban MTTQ Việt Nam phường Yên Nghĩa tổ chức Hội nghị đánh giá kết quả hoạt động 6 tháng đầu năm 2026 của các Cụm thi đua ban công tác mặt trận tổ dân phố (TDP), đồng thời phát động đợt thi đua cao điểm 45 ngày tập trung cho công tác giải phóng mặt bằng (GPMB) các dự án trọng điểm.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (27, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i160","type":"image","x":60,"y":96,"w":240,"h":130,"rotation":0,"src":"/tin/dvk/thi-dua-2.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t161","type":"text","x":60,"y":234,"w":328,"rotation":0,"content":"Phát biểu tham luận của tổ dân phố tại hội nghị. Ảnh: PT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t162","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Trong 6 tháng đầu năm 2026, ban Công tác mặt trận các tổ dân phố (TDP) đã bám sát nhiệm vụ chính trị, triển khai đồng bộ công tác tuyên truyền.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t163","type":"text","x":60,"y":302,"w":680,"rotation":0,"content":"Nổi bật là hoạt động phục vụ cuộc bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp nhiệm kỳ 2026-2031.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t164","type":"text","x":60,"y":393,"w":680,"rotation":0,"content":"Đồng thời, Mặt trận cơ sở đã phát huy vai trò nòng cốt cùng cấp ủy, chính quyền tháo gỡ 5 điểm nghẽn phát triển của địa phương, trọng tâm là vận động GPMB các dự án lớn như đường Vành đai 4 và mở rộng Quốc lộ 6 (đoạn Ba La - Xuân Mai).","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (28, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i165","type":"image","x":412,"y":96,"w":328,"h":173,"rotation":0,"src":"/tin/dvk/thi-dua-3.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t166","type":"text","x":412,"y":277,"w":328,"rotation":0,"content":"Phó Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa Lương Thị Hồng phát biểu tại hội nghị. Ảnh: PT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t167","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Nhiều mô hình “Dân vận khéo” đã cho thấy hiệu quả rõ nét. Điển hình, tổ dân phố 25 vận động thành công 14 hộ dân cùng 1 phần mộ tổ của dòng họ Nguyễn bàn giao mặt bằng phục vụ dự án Quốc lộ 6","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t168","type":"text","x":60,"y":368,"w":680,"rotation":0,"content":"đúng tiến độ; Tổ dân phố 24 hoàn thành vận động 100% hộ dân tự giác tháo dỡ công trình lấn chiếm hành lang giao thông. Những kết quả này góp phần trực tiếp tháo gỡ một trong những điểm nghẽn lớn nhất hiện nay của phường.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t169","type":"text","x":60,"y":533,"w":680,"rotation":0,"content":"Cuộc vận động “Toàn dân đoàn kết xây dựng nông thôn mới, đô thị văn minh” tiếp tục đi vào chiều sâu. Toàn phường ghi nhận 108 đám cưới và 53 đám tang thực hiện theo nếp sống mới (trong đó có 47 trường hợp hỏa táng).","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t170","type":"text","x":60,"y":696,"w":680,"rotation":0,"content":"Bên cạnh việc duy trì các mô hình “Tuyến đường sáng - xanh - sạch - đẹp”, “Ngày cuối tuần xanh”, “Tổ dân phố tự quản”, công tác chuyển đổi số cũng được đẩy mạnh qua hệ thống fanpage MTTQ phường và các nhóm Zalo cộng đồng, giúp thông tin kịp thời về an ninh trật tự, phòng cháy chữa cháy.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (29, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t171","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Phát biểu tại hội nghị, bà Lương Thị Hồng, Phó Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa nhấn mạnh: Đợt thi đua cao điểm 45 ngày là bước tiếp nối quan trọng nhằm huy động sức mạnh tổng lực để tháo gỡ dứt điểm các điểm nghẽn, tạo chuyển biến rõ nét trong GPMB, chỉnh trang đô thị và nâng cao đời sống dân cư.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t172","type":"text","x":60,"y":296,"w":680,"rotation":0,"content":"Sự vào cuộc đồng bộ từ cơ sở được kỳ vọng sẽ giúp các công trình hạ tầng trọng điểm tại Yên Nghĩa sớm về đích, mở ra không gian phát triển mới cho cửa ngõ phía Tây Thủ đô.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (30, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t173","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"GIẢI PHÓNG MẶT BẰNG","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t174","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Uỷ ban MTTQ Việt Nam phường Yên Nghĩa động viên lực lượng tuyên truyền tham gia giải phóng mặt bằng Quốc lộ 6","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t175","type":"text","x":60,"y":264,"w":680,"rotation":0,"content":"Nguồn: Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i176","type":"image","x":79,"y":303,"w":643,"h":362,"rotation":0,"src":"/tin/dvk/dong-vien-1.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t177","type":"text","x":60,"y":673,"w":680,"rotation":0,"content":"Uỷ ban MTTQ Việt Nam phường Yên Nghĩa làm việc, động viên các tổ tuyên truyền giải phóng mặt bằng tại Tổ dân phố Do Lộ. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t178","type":"text","x":60,"y":735,"w":680,"rotation":0,"content":"Chiều ngày 07/7/2026, Ủy ban MTTQ Việt Nam phường Yên Nghĩa tổ chức buổi làm việc nhằm nắm bắt tình hình, động viên lực lượng Ban Công tác Mặt trận phối hợp với UBND phường thực hiện công tác tuyên truyền giải phóng mặt bằng tại Tổ dân phố Do Lộ.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (31, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i179","type":"image","x":60,"y":96,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/dong-vien-2.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t180","type":"text","x":60,"y":289,"w":328,"rotation":0,"content":"Uỷ ban MTTQ Việt Nam phường Yên Nghĩa làm việc, động viên các tổ tuyên truyền giải phóng mặt bằng tại Tổ dân phố Do Lộ. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t181","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Tại buổi làm việc, đồng chí Lương Huệ Minh – Ủy viên Thường vụ Đảng ủy, Chủ tịch Ủy ban MTTQ Việt Nam phường đã thăm hỏi, động viên tinh thần các tổ công tác và trao tặng những phần quà nhằm khích lệ lực lượng đang trực tiếp","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t182","type":"text","x":60,"y":404,"w":680,"rotation":0,"content":"tham gia tuyên truyền, vận động Nhân dân bàn giao mặt bằng sớm phục vụ công tác thực hiện GPMB QL6.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t183","type":"text","x":60,"y":495,"w":680,"rotation":0,"content":"Đại diện Chi bộ, Tổ dân phố Do Lộ và các tổ tuyên truyền của Đảng ủy đã báo cáo tình hình, tiến độ triển khai công tác vận động các hộ gia đình di dời tài sản, bàn giao mặt bằng để thực hiện Dự án cải tạo, mở rộng Quốc lộ 6.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t184","type":"text","x":60,"y":658,"w":680,"rotation":0,"content":"Phát biểu kết luận, đồng chí Chủ tịch UB MTTQ Việt Nam phường ghi nhận, biểu dương những kết quả mà các tổ công tác đã đạt được. Đồng thời, đề nghị các đồng chí tiếp tục phát huy tinh thần trách nhiệm, tăng cường tuyên truyền, vận động để tạo sự đồng thuận trong Nhân dân, góp phần đẩy nhanh tiến độ giải phóng mặt bằng theo kế hoạch.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (32, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i185","type":"image","x":412,"y":96,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/dong-vien-3.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t186","type":"text","x":412,"y":289,"w":328,"rotation":0,"content":"Uỷ ban MTTQ Việt Nam phường Yên Nghĩa làm việc, động viên các tổ tuyên truyền giải phóng mặt bằng tại Tổ dân phố Do Lộ. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t187","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Sự vào cuộc tích cực của các lực lượng và sự đồng thuận của Nhân dân là yếu tố quan trọng góp phần thực hiện thành công Dự án cải tạo, mở rộng Quốc lộ 6, vì sự phát triển chung của thủ đô và địa địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
