  (34, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i192","type":"image","x":60,"y":96,"w":680,"h":383,"rotation":0,"src":"/tin/dvk/dong-vien-6.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t193","type":"text","x":60,"y":487,"w":680,"rotation":0,"content":"Uỷ ban MTTQ Việt Nam phường Yên Nghĩa làm việc, động viên các tổ tuyên truyền giải phóng mặt bằng tại Tổ dân phố Do Lộ. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (35, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t194","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"GIẢI PHÓNG MẶT BẰNG","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t195","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Phường Yên Nghĩa đẩy nhanh tiến độ giải phóng mặt bằng dự án cải tạo, mở rộng Quốc lộ 6","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t196","type":"text","x":60,"y":264,"w":680,"rotation":0,"content":"Nguồn: Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i197","type":"image","x":60,"y":303,"w":680,"h":383,"rotation":0,"src":"/tin/dvk/day-nhanh-1.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t198","type":"text","x":60,"y":694,"w":680,"rotation":0,"content":"Công tác tháo dỡ, bàn giao mặt bằng phục vụ Dự án cải tạo, mở rộng Quốc lộ 6 qua địa bàn phường Yên Nghĩa. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t199","type":"text","x":60,"y":756,"w":680,"rotation":0,"content":"Chiều ngày 07/7/2026, đồng chí Lê Xuân Hoàn - Chủ tịch UBND phường Yên Nghĩa cùng các đồng chí lãnh đạo phường đã trực tiếp kiểm tra, giám sát việc thi công tháo dỡ, giải phóng mặt bằng phục vụ Dự án cải tạo, mở rộng Quốc lộ 6.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (36, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i200","type":"image","x":60,"y":96,"w":249,"h":140,"rotation":0,"src":"/tin/dvk/day-nhanh-2.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t201","type":"text","x":60,"y":244,"w":328,"rotation":0,"content":"Công tác tháo dỡ, bàn giao mặt bằng phục vụ Dự án cải tạo, mở rộng Quốc lộ 6 qua địa bàn phường Yên Nghĩa. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t202","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Theo ghi nhận thực tế, đến nay đa số các hộ dân thuộc diện thu hồi đất đã đồng thuận, tích cực di chuyển tài sản, tháo dỡ công trình và bàn giao mặt bằng cho chủ đầu","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t203","type":"text","x":60,"y":335,"w":680,"rotation":0,"content":"tư theo quy định.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t204","type":"text","x":60,"y":388,"w":680,"rotation":0,"content":"Sự đồng thuận, ủng hộ và chấp hành nghiêm các chủ trương, chính sách của Nhân dân là yếu tố quan trọng góp phần đẩy nhanh tiến độ thực hiện dự án, sớm hoàn thiện hạ tầng giao thông, tạo động lực phát triển kinh tế - xã hội của địa phương.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i205","type":"image","x":412,"y":551,"w":249,"h":140,"rotation":0,"src":"/tin/dvk/day-nhanh-3.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t206","type":"text","x":412,"y":699,"w":328,"rotation":0,"content":"Công tác tháo dỡ, bàn giao mặt bằng phục vụ Dự án cải tạo, mở rộng Quốc lộ 6 qua địa bàn phường Yên Nghĩa. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t207","type":"text","x":60,"y":551,"w":328,"rotation":0,"content":"Phường Yên Nghĩa đang tập trung cao độ cho công tác giải phóng mặt bằng, phấn đấu hoàn thành việc bàn giao mặt bằng sạch theo đúng tiến độ Thành phố giao.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t208","type":"text","x":60,"y":790,"w":680,"rotation":0,"content":"UBND phường trân trọng cảm ơn sự phối hợp, đồng hành của các hộ gia đình, cá nhân trong quá trình triển khai dự án và mong tiếp tục nhận được sự đồng thuận của Nhân dân để dự án được thực hiện thuận lợi, hiệu quả.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
