  (42, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t229","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"DÂN VẬN KHÉO","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#c8a227","bold":true,"italic":false,"align":"left","lineHeight":1.62},{"id":"t230","type":"text","x":60,"y":133,"w":680,"rotation":0,"content":"Dân vận khéo ở Yên Nghĩa: Đi từng ngõ, gõ từng nhà, gỡ từng vướng mắc","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.24},{"id":"t231","type":"text","x":60,"y":223,"w":680,"rotation":0,"content":"Nguồn: Uỷ ban MTTQ Việt Nam phường Yên Nghĩa","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i232","type":"image","x":108,"y":262,"w":585,"h":329,"rotation":0,"src":"/tin/dvk/di-tung-ngo-1.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t233","type":"text","x":60,"y":599,"w":680,"rotation":0,"content":"Quang cảnh hội nghị triển khai công tác tuyên truyền, vận động giải phóng mặt bằng Dự án cải tạo, mở rộng Quốc lộ 6 tại phường Yên Nghĩa. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t234","type":"text","x":60,"y":661,"w":680,"rotation":0,"content":"Xác định giải phóng mặt bằng (GPMB) Dự án cải tạo, mở rộng Quốc lộ 6 (đoạn Ba La - Xuân Mai) là “điểm nghẽn” lớn nhất phải tập trung tháo gỡ, Ủy ban MTTQ Việt Nam phường Yên Nghĩa cùng cả hệ thống chính trị đã chọn cách làm “đi từng ngõ, gõ từng nhà, rà từng hộ”. Từ hội trường phường đến nhà văn hóa tổ dân phố, từ sân nhà dân đến công trường tháo dỡ, mỗi vướng mắc đều được nghe, được bàn và được giải quyết ngay từ cơ sở.","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (43, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t235","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Từ hội nghị của phường đến từng ngõ nhỏ","fontSize":26,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t236","type":"text","x":60,"y":141,"w":680,"rotation":0,"content":"Thực hiện đợt thi đua cao điểm 45 ngày tập trung cho công tác GPMB các dự án trọng điểm được Ban Thường trực Ủy ban MTTQ Việt Nam phường phát động ngày 19-6, Ủy ban MTTQ Việt Nam phường Yên Nghĩa phối hợp với UBND phường tổ chức hội nghị quán triệt nhiệm vụ, phân công rõ người, rõ việc, rõ tiến độ cho từng tổ công tác. Hội nghị có sự tham dự của đại diện Công an phường, các ban, ngành, đoàn thể và ban công tác Mặt trận các tổ dân phố - lực lượng trực tiếp bám địa bàn, tiếp xúc với từng hộ dân.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i237","type":"image","x":60,"y":453,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/di-tung-ngo-2.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t238","type":"text","x":60,"y":646,"w":328,"rotation":0,"content":"Đại diện Công an phường và các ban, ngành, đoàn thể dự hội nghị. Sự phối hợp giữa Công an phường với Ủy ban MTTQ Việt Nam phường là một trong những nhân tố bảo đảm an ninh trật tự trong quá trình giải phóng mặt bằng. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t239","type":"text","x":412,"y":453,"w":328,"rotation":0,"content":"Đây là bước tiếp nối của chương trình phối hợp năm 2026 giữa Công an phường và Ủy ban MTTQ Việt Nam phường trong tuyên truyền, vận động nhân dân tham gia tháo gỡ “5 điểm nghẽn” của địa phương, gồm: ùn tắc giao thông, ô nhiễm môi trường, ngập úng đô thị, vi phạm trật tự xây dựng - đất đai","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t240","type":"text","x":60,"y":809,"w":680,"rotation":0,"content":"và an toàn thực phẩm. Trong đó, GPMB Dự án cải tạo, mở rộng Quốc lộ 6 và đường Vành đai 4 - Vùng Thủ đô Hà Nội được xác định là nhiệm vụ trọng tâm, xuyên suốt của phường trong năm 2026.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (44, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t241","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Khối lượng công việc đặt ra cho cơ sở là rất lớn. Theo UBND phường Yên Nghĩa, Dự án cải tạo, nâng cấp Quốc lộ 6 có tổng diện tích thu hồi khoảng 124.297,5 m², liên quan đến 528 hộ gia đình, cá nhân có đất ở; 46 hộ có đất thương mại dịch vụ; 16 hộ có đất nông nghiệp cùng nhiều tổ chức, doanh nghiệp trên địa bàn. Phường đã ban hành 601 thông báo thu hồi đất; hơn 68.452 m² đất công đã được bàn giao cho chủ đầu tư phục vụ thi công.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i242","type":"image","x":412,"y":371,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/di-tung-ngo-3.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t243","type":"text","x":412,"y":564,"w":328,"rotation":0,"content":"Đại diện tổ công tác báo cáo kết quả tuyên truyền, vận động các hộ dân trong diện thu hồi đất. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t244","type":"text","x":60,"y":371,"w":328,"rotation":0,"content":"Tại hội nghị, các tổ công tác, ban công tác Mặt trận tổ dân phố đã báo cáo tiến độ vận động, thẳng thắn nêu những khó khăn gặp phải trong quá trình tiếp cận các hộ dân: băn khoăn về giá bồi thường, lo lắng về nơi ở sau khi bị thu hồi đất,","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t245","type":"text","x":60,"y":655,"w":680,"rotation":0,"content":"vướng mắc về nguồn gốc đất, đất dịch vụ, đất giao không đúng thẩm quyền từ nhiều năm trước. Riêng nhu cầu tái định cư, qua rà soát dự kiến có khoảng 320 hộ cần bố trí với tổng diện tích khoảng 2,1 ha, trong khi quỹ đất tái định cư hiện có mới khoảng 1,5 ha.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t246","type":"text","x":60,"y":820,"w":680,"rotation":0,"content":"Bí thư Đảng ủy, Chủ tịch HĐND phường Yên Nghĩa Nguyễn Nguyên Quân yêu cầu cả hệ thống chính trị vào cuộc đồng bộ, quyết liệt, xác định","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (45, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t247","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"rõ trách nhiệm trong công tác tuyên truyền, vận động; các đoàn thể chính trị - xã hội bám sát địa bàn, chủ động nắm bắt tâm tư, nguyện vọng của người dân, kịp thời tháo gỡ khó khăn ngay từ cơ sở, không để phát sinh các điểm nóng.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t248","type":"text","x":60,"y":259,"w":680,"rotation":0,"content":"Từ những ý kiến đó, phường thống nhất phương châm: không chờ dân đến phường, mà cán bộ chủ động xuống với dân. Ủy ban MTTQ Việt Nam phường đã thành lập tổ công tác gồm 4 nhóm phụ trách từng địa bàn dân cư để trực tiếp tuyên truyền, vận động các hộ dân trong diện thu hồi đất. Mô hình “Tổ tuyên truyền 3 rõ, 4 tốt” cùng nhóm kết nối “Alo Đoàn kết vì Yên Nghĩa hôm nay” - do Chủ tịch Ủy ban MTTQ Việt Nam phường Lương Huệ Minh làm Trưởng ban điều hành - tiếp tục được phát huy, trở thành kênh nắm bắt, phản ánh nhanh các vấn đề phát sinh ngay từ khu dân cư.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (46, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i249","type":"image","x":60,"y":96,"w":680,"h":383,"rotation":0,"src":"/tin/dvk/di-tung-ngo-4.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t250","type":"text","x":60,"y":487,"w":680,"rotation":0,"content":"Tham luận của ban công tác Mặt trận tổ dân phố về kinh nghiệm “dân vận khéo” trong vận động bàn giao mặt bằng. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t251","type":"text","x":60,"y":549,"w":680,"rotation":0,"content":"Gõ cửa từng nhà, nghe dân nói","fontSize":26,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t252","type":"text","x":60,"y":594,"w":680,"rotation":0,"content":"Những ngày cao điểm, các tổ công tác của phường chia thành nhiều nhóm, đến từng ngõ, từng hộ gia đình trong diện thu hồi đất. Không hội trường, không micro, cuộc vận động diễn ra ngay bên bàn nước sân nhà, bên chén trà, nơi người dân dễ nói thật lòng mình nhất. Theo lộ trình đề ra, phường tập trung vận động gần 300 hộ dân phối hợp thực hiện đo đạc, kiểm đếm, sau đó vận động các hộ đồng thuận với phương án bồi thường, hỗ trợ, tái định cư, phấn đấu hoàn thành bàn giao mặt bằng theo đúng tiến độ thành phố giao.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (47, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i253","type":"image","x":60,"y":96,"w":215,"h":121,"rotation":0,"src":"/tin/dvk/di-tung-ngo-5.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t254","type":"text","x":60,"y":225,"w":328,"rotation":0,"content":"Tổ công tác của phường Yên Nghĩa đến từng ngõ, từng nhà để tuyên truyền, vận động các hộ dân bàn giao mặt bằng phục vụ Dự án cải tạo, mở rộng Quốc lộ 6. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t255","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Cách làm này giúp mỗi hộ dân được giải đáp đúng vướng mắc của chính gia đình mình: diện tích kiểm đếm, nguồn gốc đất, phương án bồi thường, hỗ trợ, thời điểm bố trí tái định cư.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t256","type":"text","x":60,"y":340,"w":680,"rotation":0,"content":"Đến nay, phường đã xác nhận nguồn gốc đất cho 44 trường hợp, hoàn thành biên bản kiểm đếm đối với 108 trường hợp và niêm yết dự thảo phương án bồi thường, hỗ trợ đối với 43 trường hợp.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t257","type":"text","x":60,"y":468,"w":680,"rotation":0,"content":"Không ít câu hỏi của bà con là những việc khó. Đó là sự chênh lệch giá đất bồi thường giữa Dự án Quốc lộ 6 và Dự án Vành đai 4 trên cùng trục Quốc lộ 6A - tại vị trí 1 đoạn từ đường sắt đến cầu Mai Lĩnh, giá bồi thường của Dự án Vành đai 4 được phê duyệt hơn 90,8 triệu đồng/m², trong khi mức áp dụng với Dự án Quốc lộ 6 khoảng 52,3 triệu đồng/m². Đó còn là 24 thửa đất dịch vụ bị thu hồi với diện tích khoảng 500 m², mà nhiều hộ mong muốn được bố trí đất cùng mục đích sử dụng thay vì chỉ nhận bồi thường bằng tiền.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (48, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i258","type":"image","x":412,"y":96,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/di-tung-ngo-6.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t259","type":"text","x":412,"y":289,"w":328,"rotation":0,"content":"Lãnh đạo phường, Ủy ban MTTQ Việt Nam phường, Công an phường và các đoàn thể cùng trao đổi, đối thoại với hộ dân ngay tại gia đình. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t260","type":"text","x":60,"y":96,"w":328,"rotation":0,"content":"Với những nội dung này, quan điểm của phường được Chủ tịch UBND phường Yên Nghĩa Lê Xuân Hoàn nêu rõ: “Quan điểm của phường là thực hiện đúng quy định của pháp luật nhưng phải đảm bảo hài hòa lợi ích giữa Nhà nước","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t261","type":"text","x":60,"y":404,"w":680,"rotation":0,"content":"và người dân. Những nội dung vượt thẩm quyền sẽ được tổng hợp, báo cáo thành phố và các sở, ngành xem xét giải quyết để tạo sự đồng thuận cao nhất trong quá trình triển khai dự án”.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t262","type":"text","x":60,"y":532,"w":680,"rotation":0,"content":"Theo Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa Lương Huệ Minh, công tác tuyên truyền chỉ thực sự hiệu quả khi bám sát cơ sở, gắn với những vấn đề cụ thể của người dân: “Chúng tôi xác định phải đưa chủ trương đến đúng đối tượng, đúng thời điểm, bằng những hình thức phù hợp, dễ hiểu, dễ tiếp cận. Khi người dân hiểu rõ quyền lợi và trách nhiệm của mình, họ sẽ chủ động tham gia, từ đó tạo sự đồng thuận trong triển khai các nhiệm vụ tại địa phương”.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t263","type":"text","x":60,"y":807,"w":680,"rotation":0,"content":"Song song với vận động nhân dân, Ủy ban MTTQ Việt Nam phường cũng thường xuyên nắm bắt tình hình, thăm hỏi, động viên chính lực lượng đi vận động.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (49, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t264","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Chiều 7-7-2026, Chủ tịch Ủy ban MTTQ Việt Nam phường Lương Huệ Minh đã có buổi làm việc với chi bộ, ban công tác Mặt trận và các tổ tuyên truyền tại Tổ dân phố Do Lộ, trao tặng những phần quà khích lệ lực lượng đang trực tiếp bám địa bàn vận động các hộ dân di dời tài sản, bàn giao mặt bằng.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i265","type":"image","x":60,"y":296,"w":680,"h":383,"rotation":0,"src":"/tin/dvk/di-tung-ngo-7.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t266","type":"text","x":60,"y":687,"w":680,"rotation":0,"content":"Cán bộ phường giải thích cụ thể chính sách bồi thường, hỗ trợ, tái định cư cho từng trường hợp. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (50, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t267","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Nhà văn hóa tổ dân phố - nơi bàn việc chung","fontSize":26,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t268","type":"text","x":60,"y":141,"w":680,"rotation":0,"content":"Song song với việc đến từng nhà, phường duy trì các hội nghị tuyên truyền, họp dân tại nhà văn hóa tổ dân phố. Đây là nơi phương án bồi thường, hỗ trợ và tiến độ dự án được công khai, để người dân cùng bàn, cùng giám sát theo đúng phương châm “Dân biết, dân bàn, dân làm, dân kiểm tra, dân thụ hưởng”.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i269","type":"image","x":60,"y":341,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/di-tung-ngo-8.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t270","type":"text","x":60,"y":534,"w":328,"rotation":0,"content":"Buổi đối thoại tại nhà một hộ dân thuộc diện thu hồi đất. Người dân được nêu ý kiến, kiến nghị trực tiếp với lãnh đạo phường và các cơ quan chuyên môn. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t271","type":"text","x":412,"y":341,"w":328,"rotation":0,"content":"Nhờ kiên trì tuyên truyền, nhiều tổ dân phố đã trở thành điểm sáng “Dân vận khéo”. Tổ dân phố 25 vận động thành công 14 hộ dân cùng một phần mộ tổ của dòng họ Nguyễn bàn giao mặt bằng đúng tiến độ;","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t272","type":"text","x":60,"y":649,"w":680,"rotation":0,"content":"tổ dân phố 24 hoàn thành vận động 100% hộ dân tự giác tháo dỡ công trình lấn chiếm hành lang giao thông.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t273","type":"text","x":60,"y":740,"w":680,"rotation":0,"content":"Tại tổ dân phố 17, mô hình “Tuyến đường quân - dân tự quản” tiếp tục phát huy hiệu quả.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (51, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t274","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Ông Bùi Văn Binh, Bí thư Chi bộ, Trưởng ban Công tác Mặt trận tổ dân phố 17 cho biết: “Muốn người dân làm theo, trước hết, cán bộ, đảng viên phải gương mẫu, sau đó là kiên trì tuyên truyền để người dân hiểu. Khi đã hiểu đúng, người dân sẽ tự giác thực hiện, không cần nhắc nhở nhiều”. Với 25 hộ dân và 4 cơ quan trên địa bàn, công tác vận động GPMB các dự án Vành đai 4 và Quốc lộ 6 tại đây đạt kết quả tích cực: 15/17 hộ đã chấp hành tháo dỡ, 2 hộ còn lại đồng thuận và cam kết hoàn trả mặt bằng trước ngày 30-6.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"i275","type":"image","x":412,"y":408,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/di-tung-ngo-9.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t276","type":"text","x":412,"y":601,"w":328,"rotation":0,"content":"Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa trao tài liệu tuyên truyền và phần quà động viên hộ dân chấp hành tốt chủ trương giải phóng mặt bằng. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t277","type":"text","x":60,"y":408,"w":328,"rotation":0,"content":"Cùng với cách làm truyền thống, công tác chuyển đổi số cũng được đẩy mạnh.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t278","type":"text","x":60,"y":716,"w":680,"rotation":0,"content":"Hệ thống fanpage của MTTQ phường và các nhóm Zalo cộng đồng giúp thông tin về tiến độ dự án, an ninh trật tự, phòng cháy chữa cháy đến với người dân kịp thời, đồng thời là kênh để bà con phản ánh ngược trở lại những vướng mắc phát sinh.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (52, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t279","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Theo Phó Chủ tịch Ủy ban MTTQ Việt Nam phường Yên Nghĩa Lương Thị Hồng, đợt thi đua cao điểm 45 ngày là bước tiếp nối quan trọng nhằm huy động sức mạnh tổng lực để tháo gỡ dứt điểm các điểm nghẽn, tạo chuyển biến rõ nét trong GPMB, chỉnh trang đô thị và nâng cao đời sống dân cư.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t280","type":"text","x":60,"y":296,"w":680,"rotation":0,"content":"Từ đồng thuận đến mặt bằng sạch","fontSize":26,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t281","type":"text","x":60,"y":341,"w":680,"rotation":0,"content":"Kết quả của công tác dân vận được đo bằng chính mặt bằng bàn giao cho chủ đầu tư. Chiều 7-7-2026, Chủ tịch UBND phường Yên Nghĩa Lê Xuân Hoàn cùng các đồng chí lãnh đạo phường đã trực tiếp kiểm tra, giám sát việc thi công tháo dỡ, giải phóng mặt bằng. Theo ghi nhận thực tế, đến nay đa số các hộ dân thuộc diện thu hồi đất đã đồng thuận, tích cực di chuyển tài sản, tháo dỡ công trình và bàn giao mặt bằng cho chủ đầu tư theo quy định.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t282","type":"text","x":60,"y":616,"w":680,"rotation":0,"content":"Bên cạnh kết quả đạt được, phường xác định vẫn còn những việc khó cần tiếp tục tháo gỡ, nhất là quỹ đất tái định cư, chênh lệch giá bồi thường giữa các dự án trên cùng một trục đường, việc xử lý đất dịch vụ, đất giao không đúng thẩm quyền từ nhiều năm trước và các công trình tín ngưỡng, phần mộ nằm trong phạm vi dự án. Tiến độ hoàn thiện bản đồ thu hồi đất cũng cần được đẩy nhanh khi toàn tuyến có 18 tờ bản đồ nhưng mới hoàn thiện ký xác nhận được 4 tờ.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (53, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i283","type":"image","x":60,"y":96,"w":680,"h":383,"rotation":0,"src":"/tin/dvk/di-tung-ngo-10.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t284","type":"text","x":60,"y":487,"w":680,"rotation":0,"content":"Hội nghị tuyên truyền, vận động giải phóng mặt bằng được tổ chức tại nhà văn hóa tổ dân phố. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (54, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i285","type":"image","x":60,"y":96,"w":328,"h":185,"rotation":0,"src":"/tin/dvk/di-tung-ngo-11.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t286","type":"text","x":60,"y":289,"w":328,"rotation":0,"content":"Đại diện tổ dân phố nêu ý kiến, kiến nghị của các hộ dân tại hội nghị. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"t287","type":"text","x":412,"y":96,"w":328,"rotation":0,"content":"Những vấn đề dân sinh khác cũng được người dân gửi gắm qua các hội nghị tiếp xúc cử tri trước kỳ họp thứ hai HĐND phường khóa II, nhiệm kỳ 2026-2031: đẩy nhanh tiến độ cấp giấy chứng nhận quyền","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t288","type":"text","x":60,"y":357,"w":680,"rotation":0,"content":"sử dụng đất, sớm giải quyết quyền lợi liên quan đến đất dịch vụ, nâng cấp hệ thống giao thông, cải thiện thoát nước chống ngập úng cục bộ, cải tạo nhà văn hóa và hỗ trợ đào tạo nghề, chuyển đổi việc làm cho các hộ bị thu hồi đất. Toàn bộ kiến nghị được tiếp thu, tổng hợp báo cáo tại kỳ họp và chuyển các cơ quan có thẩm quyền xem xét, giải quyết theo quy định.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62},{"id":"t289","type":"text","x":60,"y":559,"w":680,"rotation":0,"content":"Có thể thấy, “điểm nghẽn” lớn nhất trong GPMB không nằm ở khối lượng công việc, mà ở sự đồng thuận trong lòng dân. Bằng cách đi từng ngõ, gõ từng nhà, gỡ từng vướng mắc, phường Yên Nghĩa đang từng bước biến những việc khó thành việc chung của cả cộng đồng, góp phần sớm bàn giao mặt bằng sạch cho các dự án trọng điểm, mở ra không gian phát triển mới cho cửa ngõ phía Tây Thủ đô.","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.62}]'),
  (55, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i290","type":"image","x":130,"y":96,"w":540,"h":320,"rotation":0,"src":"/tin/dvk/di-tung-ngo-12.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t291","type":"text","x":60,"y":424,"w":680,"rotation":0,"content":"Lãnh đạo phường Yên Nghĩa trực tiếp trả lời, làm rõ những nội dung người dân quan tâm ngay tại buổi họp dân. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i292","type":"image","x":130,"y":486,"w":540,"h":320,"rotation":0,"src":"/tin/dvk/di-tung-ngo-13.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t293","type":"text","x":60,"y":814,"w":680,"rotation":0,"content":"Lãnh đạo phường Yên Nghĩa kiểm tra thực địa công tác tháo dỡ công trình, bàn giao mặt bằng phục vụ Dự án cải tạo, mở rộng Quốc lộ 6. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (56, '#ffffff', '/tin/bg-trang.webp', '[{"id":"i294","type":"image","x":130,"y":96,"w":540,"h":320,"rotation":0,"src":"/tin/dvk/di-tung-ngo-14.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t295","type":"text","x":60,"y":424,"w":680,"rotation":0,"content":"Các tổ công tác khảo sát những vị trí còn vướng mắc trong phạm vi thu hồi đất để đề xuất phương án xử lý phù hợp. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4},{"id":"i296","type":"image","x":130,"y":486,"w":540,"h":320,"rotation":0,"src":"/tin/dvk/di-tung-ngo-15.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#c8a227"},{"id":"t297","type":"text","x":60,"y":814,"w":680,"rotation":0,"content":"Bên lề hội nghị tiếp xúc cử tri trước kỳ họp thứ hai HĐND phường Yên Nghĩa khóa II, nhiệm kỳ 2026-2031 (ngày 3-6-2026), lãnh đạo phường trao quà động viên ban công tác Mặt trận và tổ tuyên truyền tổ dân phố. Ảnh: PV","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.4}]'),
  (57, '#0b3f8f', '/tin/bg-bia-sau.webp', '[{"id":"i298","type":"image","x":345,"y":360,"w":110,"h":110,"rotation":0,"src":"/brand/emblem.webp","radius":0,"opacity":1,"fit":"contain","borderWidth":0,"borderColor":"#c8a227"},{"id":"t299","type":"text","x":60,"y":500,"w":680,"rotation":0,"content":"UỶ BAN MẶT TRẬN TỔ QUỐC VIỆT NAM\nPHƯỜNG YÊN NGHĨA","fontSize":33,"fontFamily":"\"Times New Roman\", Times, serif","color":"#ffffff","bold":true,"italic":false,"align":"center","lineHeight":1.35},{"id":"t300","type":"text","x":60,"y":640,"w":680,"rotation":0,"content":"BẢN TIN DÂN VẬN KHÉO  ·  NĂM 2026","fontSize":24,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#ffd76a","bold":true,"italic":false,"align":"center","lineHeight":1.4},{"id":"t301","type":"text","x":60,"y":692,"w":680,"rotation":0,"content":"“Dân biết, dân bàn, dân làm, dân kiểm tra, dân thụ hưởng”","fontSize":22,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#cfe0ff","bold":false,"italic":true,"align":"center","lineHeight":1.5}]')
) as p(ord, bg, bgimg, els);
